import assert from 'node:assert/strict';

export async function runMotionInspectorSmoke(page){
 const viewport=page.viewport(),previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()}));
 try{
  await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,elements:[]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});
  const before=await page.evaluate(()=>({project:JSON.stringify(project),stored:localStorage.getItem(STORE_KEY),assets:project.assets.images.length}));
  async function ready(id){await page.waitForFunction(id=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return id?d?.querySelector('[data-id="'+id+'"].nw-motion-selected'):d?.querySelector('[data-motion-canvas]');},{},id);}
  async function visible(){return page.$$eval('[data-motion-content]',ns=>ns.filter(n=>n.getClientRects().length&&getComputedStyle(n).visibility!=='hidden').map(n=>+n.dataset.motionContent));}
  async function choose(id,index){await page.click('[data-motion-layer="'+id+'"]');await ready(id);assert.deepEqual(await visible(),[index]);assert.equal(await page.$eval('[data-motion-content-panel]',n=>n.hidden),false);}
  async function type(index,text){await page.click('[data-motion-content="'+index+'"]');await page.keyboard.down('Control');await page.keyboard.press('A');await page.keyboard.up('Control');await page.keyboard.type(text);await page.keyboard.press('Tab');await page.waitForFunction(({id,text})=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('[data-id="'+id+'"].nw-motion-selected')?.textContent===text,{},{id:ids[index],text});}
  async function pose(id,selector='.nw-motion-dialog iframe',gid){return page.evaluate(({id,selector,gid})=>{const f=document.querySelector(selector),d=f.contentDocument;f.contentWindow.__NAG_SCROLL_DIRECTOR[gid||d.querySelector('.sc').dataset.id].set(.2);const n=d.querySelector('[data-id="'+id+'"]');return {vars:['x','y','z','rx','ry','scale','rot','opacity','blur'].map(k=>n.style.getPropertyValue('--nw-sd-'+k)),src:n.querySelector('img')?.getAttribute('src')};},{id,selector,gid});}
  await page.click('.tb-left [data-motion-open]');await ready();assert.equal(await page.$eval('[data-motion-composition-settings]',n=>n.open),false);assert.equal(await page.$eval('[data-motion-config="duration"]',n=>n.getClientRects().length),0);await page.click('[data-motion-composition-settings]>summary');await page.$eval('.nw-motion-dialog iframe',f=>f.contentDocument.body.dataset.settingsProbe='old');await page.click('[data-motion-config="duration"]');await page.keyboard.down('Control');await page.keyboard.press('A');await page.keyboard.up('Control');await page.keyboard.type('4');await page.keyboard.press('Tab');await page.waitForFunction(()=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.querySelector('[data-motion-canvas]')&&!d.body.dataset.settingsProbe;});assert.equal(await page.$eval('[data-motion-composition-settings]',n=>n.open),true);assert.equal(await page.$eval('[data-motion-content-panel]',n=>n.hidden),true);assert.deepEqual(await visible(),[],'No unrelated content controls before selection');await page.click('[data-motion-library-tab="elements"]');const ids=await page.$$eval('[data-motion-layer]',ns=>ns.map(n=>n.dataset.motionLayer));await choose(ids[0],0);const originalPose=await pose(ids[0]);assert.equal(await page.$eval('[data-motion-content="0"]',n=>n.tagName),'SELECT');assert.equal(await page.$eval('[data-motion-upload-open="0"]',n=>n.getClientRects().length>0),true);assert.equal(await page.$eval('[data-motion-upload-open="1"]',n=>n.getClientRects().length),0);assert.equal(await page.$eval('[data-motion-text-style-panel]',n=>n.hidden),true);
  assert.ok(await page.$eval('[data-motion-content-panel]',n=>{const name=n.previousElementSibling,geometry=n.parentElement.querySelector('[data-motion-position]').closest('.crow');return name.querySelector('[data-motion-element-name]')&&!!(n.compareDocumentPosition(geometry)&Node.DOCUMENT_POSITION_FOLLOWING);}),'Content sits after the name and before geometry');
  const replacement=await page.$eval('[data-motion-content="1"]',n=>n.value);await page.select('[data-motion-content="0"]',replacement);await page.waitForFunction(id=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument,a=d?.querySelector('[data-id="'+id+'"].nw-motion-selected img'),b=d?.querySelectorAll('.im-hov img')[1];return a?.complete&&a.naturalWidth>0&&a.getAttribute('src')===b?.getAttribute('src');},{},ids[0]);assert.deepEqual(await visible(),[0]);const prepared=await pose(ids[0]);assert.deepEqual(prepared.vars,originalPose.vars,'Replacing selected content preserves movement');
  await choose(ids[4],4);assert.equal(await page.$eval('[data-motion-text-style-panel]',n=>n.hidden),false);assert.ok(await page.$eval('[data-motion-text-style-panel]',n=>n.previousElementSibling.hasAttribute('data-motion-content-panel')&&!!(n.compareDocumentPosition(n.parentElement.querySelector('[data-motion-position]').closest('.crow'))&Node.DOCUMENT_POSITION_FOLLOWING)),'Text style follows its content before geometry and movement');assert.equal(await page.$eval('[data-motion-content="4"]',n=>n.type),'text');const title='Título <b>propio</b>';await type(4,title);assert.deepEqual(await visible(),[4]);assert.equal(await page.$eval('[data-motion-content="3"]',n=>n.getClientRects().length),0);await choose(ids[5],5);await type(5,'Descripción propia');await choose(ids[4],4);assert.equal(await page.$eval('[data-motion-content="4"]',n=>n.value),title);
  // Canvas selection synchronizes the same contextual content panel.
  const f=await (await page.$('.nw-motion-dialog iframe')).contentFrame(),label=await f.$('[data-id="'+ids[3]+'"]');await label.focus();await page.keyboard.press('Space');assert.deepEqual(await visible(),[3]);await type(3,'Mi estudio');assert.deepEqual(await visible(),[3]);
  await page.click('[data-motion-library-tab="library"]');await page.click('[data-motion-template="soft-orbit"]');await page.waitForFunction(()=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('.hd')?.textContent==='Diseño en movimiento.');assert.deepEqual(await visible(),[]);assert.equal(await page.$eval('[data-motion-composition-settings]',n=>n.open),false);await page.click('[data-motion-template="iso-focus"]');await ready(ids[3]);assert.equal(await page.$eval('[data-motion-composition-settings]',n=>n.open),true);assert.equal(await page.$eval('[data-motion-config="duration"]',n=>n.value),'4');assert.deepEqual(await visible(),[3]);assert.equal(await page.$eval('[data-motion-content="3"]',n=>n.value),'Mi estudio');assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>localStorage.getItem(STORE_KEY)),before.stored);assert.equal(await page.evaluate(()=>history.length),0);await page.click('[data-motion-insert-group]');const inserted=await page.evaluate(()=>{const g=sec().elements.find(e=>e.nwMotionInstance);return {project:JSON.stringify(project),gid:g.id,members:sec().elements.filter(e=>e.parent===g.id),assets:project.assets.images.length,duration:g.nwMotionInstance.duration};});assert.equal(inserted.duration,4);assert.equal(inserted.members.find(e=>e.id===ids[0]).assetId,replacement);assert.equal(inserted.members.find(e=>e.id===ids[4]).text,title);assert.equal(inserted.members.find(e=>e.id===ids[5]).text,'Descripción propia');assert.equal(inserted.members.find(e=>e.id===ids[3]).text,'Mi estudio');assert.equal(inserted.assets,before.assets+2);
  await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),inserted.gid);await ready();assert.deepEqual(await visible(),[]);await page.click('[data-motion-library-tab="elements"]');await choose(ids[5],5);await type(5,'Descripción guardada');await page.click('[data-motion-save]');const saved=await page.evaluate(gid=>({project:JSON.stringify(project),members:sec().elements.filter(e=>e.parent===gid),groups:sec().elements.filter(e=>e.nwMotionInstance).length}),inserted.gid);assert.equal(saved.groups,1);assert.deepEqual(saved.members,inserted.members.map(e=>e.id===ids[5]?{...e,text:'Descripción guardada'}:e));
  await page.setViewport({width:390,height:844,deviceScaleFactor:1});await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),inserted.gid);await ready();await page.click('[data-motion-library-tab="elements"]');await choose(ids[4],4);await page.click('[data-motion-content="4"]');assert.ok(await page.$eval('[data-motion-content="4"]',n=>{const r=n.getBoundingClientRect(),box=n.closest('.nw-motion-inspector-scroll').getBoundingClientRect();return r.top>=box.top&&r.bottom<=box.bottom+1;}),'Selected content remains reachable on a compact screen');await page.click('[data-motion-close]');assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);await page.setViewport(viewport);await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),inserted.project);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);
  await page.evaluate(()=>{const f=document.createElement('iframe');f.id='inspector-export';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(gid=>document.querySelector('#inspector-export')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[gid],{},inserted.gid);assert.deepEqual(await pose(ids[0],'#inspector-export',inserted.gid),prepared);assert.equal(await page.$eval('#inspector-export',(f,id)=>f.contentDocument.querySelector('[data-id="'+id+'"]')?.textContent,ids[5]),'Descripción guardada');
  console.log('Inspector Motion Lab: contenido único y contextual, nombre/contenido antes de geometría, imagen/texto reales, lienzo/lista, regeneración y borradores, guardado exacto, móvil, historial y exportación OK');
 }finally{
  await page.setViewport(viewport);await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();document.querySelector('#inspector-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);
 }
}
